<template>
  <figure class="project-demo" @click.stop @keydown.stop>
    <div class="project-demo-frame">
      <video
        ref="video"
        :src="started ? src : undefined"
        :poster="started ? poster : undefined"
        :controls="started && !failed"
        :aria-hidden="!started || failed"
        :aria-label="title"
        :tabindex="started && !failed ? 0 : -1"
        preload="none"
        playsinline
        @play="onPlay"
        @pause="onPause"
        @ended="onPause"
        @error="onError"
      />
      <button v-if="!started || failed" class="project-demo-trigger" type="button" :aria-label="`Watch demo, ${title}, ${duration}`" @click="play">
        <img :src="poster" alt="" width="1440" height="810" loading="lazy" />
        <span class="project-demo-play" aria-hidden="true">
          <svg viewBox="0 0 24 24" focusable="false"><path d="M9 5.5 19 12 9 18.5Z" /></svg>
          <span class="project-demo-play-copy">
            <span>Watch demo</span>
            <span class="project-demo-duration">{{ duration }}</span>
          </span>
        </span>
      </button>
    </div>
    <div v-if="failed" class="project-demo-error" role="status">
      The video could not play. <a :href="src" target="_blank" rel="noopener">Open the video</a>
    </div>
    <figcaption class="project-demo-caption">{{ caption }} (redacted)</figcaption>
  </figure>
</template>

<script>
export default {
  name: 'ProjectDemoVideo',
  props: {
    title: { type: String, required: true },
    caption: { type: String, required: true },
    src: { type: String, required: true },
    poster: { type: String, required: true },
    duration: { type: String, required: true },
  },
  data: () => ({ started: false, failed: false }),
  mounted() {
    window.addEventListener('view-summary-play', this.otherAudio);
    document.addEventListener('visibilitychange', this.visibilityChanged);
    this._visibilityObserver = new IntersectionObserver(([entry]) => {
      const video = this.$refs.video;
      if (!entry.isIntersecting && !document.fullscreenElement && !video?.webkitDisplayingFullscreen) this.pause();
    });
    this._visibilityObserver.observe(this.$el);
  },
  beforeUnmount() {
    this.pause();
    this._visibilityObserver?.disconnect();
    window.removeEventListener('view-summary-play', this.otherAudio);
    document.removeEventListener('visibilitychange', this.visibilityChanged);
  },
  methods: {
    async play() {
      const retry = this.failed;
      this.started = true;
      this.failed = false;
      await this.$nextTick();
      const video = this.$refs.video;
      if (!video) return;
      if (retry) video.load();
      video.focus({ preventScroll: true });
      try { await video.play(); }
      catch (error) { if (error.name !== 'AbortError') this.onError(); }
    },
    onPlay() {
      if (document.hidden || this.$refs.video?.paused) { this.pause(); return; }
      this._announcedPlayback = true;
      window.dispatchEvent(new CustomEvent('view-summary-play', { detail: this }));
    },
    onPause() {
      if (!this._announcedPlayback) return;
      this._announcedPlayback = false;
      window.dispatchEvent(new CustomEvent('view-summary-pause', { detail: this }));
    },
    onError() { this.failed = true; this.onPause(); },
    pause() { this.$refs.video?.pause(); this.onPause(); },
    otherAudio(event) { if (event.detail !== this) this.pause(); },
    visibilityChanged() { if (document.hidden) this.pause(); },
  },
};
</script>

